export function count(e,o,t=`${o}s`){return`${e} ${e===1?o:t}`}export function welcomeLine(e){const o=e.dueToday+e.overdue;return o>0?`Welcome back. ${count(o,"follow-up")} ${o===1?"is":"are"} waiting for you today.`:e.upcoming>0?`Welcome back. The desk is clear today, and ${count(e.upcoming,"event")} ${e.upcoming===1?"is":"are"} on the calendar this week.`:e.applications>0?"Welcome back. The desk is clear today.":"Welcome back. The office is ready whenever you are."}export function pageTitle(e,o){const t=o.dueToday+o.overdue;return t>0?`(${t}) ${e}`:e}export function storageNote(e,o){switch(e){case"unavailable":return"This browser is not letting the office save, so anything you enter will be gone when the tab closes. A private window is the usual reason.";case"newer":return"Your office was saved by a newer version of this page, so it has been left exactly as it was. Reloading the page should open it.";case"unreadable":return"The saved office could not be read, so it has been left untouched and nothing will be saved over it.";default:return o&&o.warn?"Your office is using most of the space this browser allows. Saving a backup soon would be wise.":""}}
